class Solution {
public:
    bool isMonotonic(vector<int>& nums) {
        bool up = false, down = false;
        for (int i = 1; i < (int)nums.size(); i++) {
            if (nums[i] > nums[i - 1]) up = true;
            if (nums[i] < nums[i - 1]) down = true;
        }
        return !(up && down);
    }
};
